import React from 'react';

import Sunglasses from '@pohodnik/icons/svg/RealWorld/Sunglasses';

import { selectOneEquipItemInModal } from '@apps/Equip/components/SelectOneEquipModal';
import { round } from '@helpers/mathHelper';
import { err } from '@helpers/notificationHelper';
import PohAva from '@ui-kit/Ava';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohImageUploader from '@ui-kit/ImageUploader';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohLoader from '@ui-kit/Loader';
import PohSelect from '@ui-kit/Select';

import { mapCategoriesToLabels } from './mappers';
import { getEmptyEquip } from '../../../@mappers/equip.mapper';
import { addEquip, getEquipCategories } from '../../../@services/equip.service';
import { IEquip, IEquipCategory } from '../../../@types/equip.types';
import { getEquipSuggest } from '../../HikingEquipAdmin/addCustomEquip/services';
import EquipOptionsWidget from '../components/EquipOptionsWidget';

interface IAddEquipModalProps {
  data?: IEquip;
  onSave: (savedEquip: IEquip) => void;
  onCancel: () => void;
}

const AddEquipModal: React.FC<IAddEquipModalProps> = ({ data, onSave, onCancel }) => {
  const [modelData, setModelData] = React.useState<IEquip>(data ?? getEmptyEquip());
  const [categories, setCategories] = React.useState<IEquipCategory[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const [isSaving, setIsSaving] = React.useState(false);

  React.useEffect(() => {
    getEquipCategories()
      .then(setCategories)
      .catch(err)
      .finally(() => setIsLoading(false));
  }, []);

  const handleSave = async () => {
    try {
      setIsSaving(true);
      const id = await addEquip(modelData);
      if (id && id > 0) {
        onSave({ ...modelData, id });
      }
    } catch (e) {
      err(e as Error);
    } finally {
      setIsSaving(false);
    }
  };

  const handleChange =
    <T,>(fieldName: keyof IEquip) =>
    (value: T) =>
      setModelData((cur) => ({ ...cur, [fieldName]: value }));

  if (isLoading) {
    return <PohLoader />;
  }

  return (
    <PohContainer<'form'>
      as="form"
      style={{ minWidth: 340, minHeight: 320 }}
      onSubmit={(e) => {
        e.preventDefault();
        handleSave();
      }}
    >
      <PohRow>
        <PohCol
          sm={8}
          className="mb-sm-3"
          style={{ display: 'flex', flexDirection: 'column', gap: 8 }}
        >
          <PohInput
            label="Название"
            type={InputTypes.autocomplete}
            value={modelData.name}
            autoFocus
            onChange={(sel: any) => {
              if (sel?.text) {
                setModelData({ ...modelData, ...sel, name: sel.text });
              }
            }}
            // onBlur={(a, b) => console.log('PohInputBlur', a, b)}
            onRealChange={(val: any) => handleChange<string>('name')(val?.text || val || '')}
            autocompleteOpts={{
              data: getEquipSuggest,
              renderItem: (props: any) => {
                // eslint-disable-next-line react/prop-types
                const { text, photo, weight, value } = props;
                return (
                  <div className="d-flex justify-content-between align-items-center flex-nowrap ms-n3 me-n3">
                    <div className="d-flex align-items-center">
                      <PohAva
                        src={photo}
                        alt={text}
                        width={32}
                        icon={<Sunglasses />}
                        className="me-2"
                      />
                      {text}
                    </div>
                    <EquipOptionsWidget weight={round(weight / 1000)} value={round(+value)} />
                  </div>
                ) as React.ReactElement<any>;
              },
              allowCustom: true,
            }}
          />

          <PohRow>
            <PohCol sm={6}>
              <PohInput
                label="Вес, грамм"
                type={InputTypes.number}
                min={0}
                max={20000}
                step={0.01}
                maxLength={8}
                value={modelData.weight.toString()}
                onChange={handleChange('weight')}
                required
              />
            </PohCol>
            <PohCol sm={6}>
              <PohInput
                label="Объем, литр"
                type={InputTypes.number}
                min={0.1}
                max={150}
                step={0.01}
                maxLength={6}
                value={modelData.value.toString()}
                onChange={handleChange('value')}
                required
              />
            </PohCol>
          </PohRow>
          {categories == null ? (
            <PohLoader />
          ) : (
            <PohSelect
              allowEmpty
              placeholder="Без категории"
              label="Категория"
              options={categories.map(mapCategoriesToLabels)}
              value={modelData?.id_category}
              onChange={handleChange('id_category')}
            />
          )}

          <div>
            <PohInput
              readOnly
              placeholder="Не выбран"
              label="Родитель"
              defaultValue={modelData.id_parent ?? ''}
              onClick={async () => {
                const eq = await selectOneEquipItemInModal({});
                handleChange('id_parent')(eq.id);
              }}
              onDoubleClick={async () => {
                handleChange('id_parent')(null);
              }}
            />
          </div>

          <PohCheckbox
            onChange={handleChange('is_musthave')}
            checked={modelData.is_musthave}
            label="Обязательное"
          />
          <PohCheckbox
            onChange={handleChange('is_group')}
            checked={modelData.is_group}
            label="Групповое"
          />
          <PohCheckbox
            onChange={handleChange('is_archive')}
            checked={modelData.is_archive}
            label="Архивное"
          />
        </PohCol>
        <PohCol sm={4}>
          <PohImageUploader
            width={255}
            height={255}
            ratio={1}
            sizes={[255]}
            src={modelData.photo}
            onChange={(src) => {
              handleChange('photo')(src);
            }}
            folder="images/equip"
          />
        </PohCol>
      </PohRow>
      <footer className="mt-4">
        <PohButton variant={ButtonVariant.Secondary} onClick={onCancel}>
          Отмена
        </PohButton>{' '}
        &nbsp;
        <PohButton variant={ButtonVariant.Primary} type="submit" disabled={isSaving}>
          Сохранить
        </PohButton>
      </footer>
    </PohContainer>
  );
};

export default AddEquipModal;
